// src/utils/parseToGraph.js

// Simple example parser that converts each line of code into nodes and edges
export function parseToGraph(code) {
  const lines = code.split('\n').map(line => line.trim()).filter(Boolean);

  const nodes = [];
  const edges = [];

  let y = 50;

  lines.forEach((line, index) => {
    const id = `${index}`;
    nodes.push({
      id,
      data: { label: line },
      position: { x: 250, y },
      style: {
        background: '#111827',
        color: '#fff',
        border: '1px solid #9333ea',
        borderRadius: 8,
        padding: 10,
        fontSize: 12,
        width: 300,
      },
    });

    if (index > 0) {
      edges.push({
        id: `e${index - 1}-${index}`,
        source: `${index - 1}`,
        target: id,
        animated: true,
      });
    }

    y += 80;
  });

  return [...nodes, ...edges];
}

// Default code templates for each language
export const codeTemplates = {
  python: `def greet(name):
    if name:
        print("Hello", name)
    else:
        print("Hello world")`,

  javascript: `function greet(name) {
    if (name) {
        console.log("Hello", name);
    } else {
        console.log("Hello world");
    }
}`,

  java: `class Main {
    public static void main(String[] args) {
        System.out.println("Hello, World!");
    }
}`,

  c: `#include <stdio.h>
int main() {
    printf("Hello, World!");
    return 0;
}`,

  cpp: `#include <iostream>
using namespace std;
int main() {
    cout << "Hello, World!";
    return 0;
}`,

  sql: `SELECT * FROM users WHERE age > 18;`,

  html: `<html>
  <head><title>Hello</title></head>
  <body><h1>Hello World</h1></body>
</html>`
};
